// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        uint64 maxUint64 = type(uint64).max;

        vm.prank(depositor);
        c.setL1BlockValues(
            1,
            100,
            1000,
            bytes32(uint256(1)),
            maxUint64,
            bytes32(uint256(2)),
            2000,
            3000
        );

        uint64 storedSequence = c.sequenceNumber();
        assertTrue(storedSequence == maxUint64, "Sequence number should equal the input maxUint64; buggy version wraps to 0");
    }
}
